using Smiley.Flow;
using Smiley.View;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace Smiley.Web
{
    /// <summary>
    /// The portal's frame loop: the init timeout, and watching for play starting and stopping.
    /// </summary>
    /// <remarks>
    /// ⓘ <b>Created at runtime, never placed in a scene.</b> The scenes are generated by
    /// <c>SceneBuilder</c>, and an object that exists only when a portal is present keeps the
    /// phone builds and every fixture free of it. ⓘ It watches rather than being told, so no
    /// gameplay file had to learn the portal exists: <see cref="GameplayRule"/> reads the flow's
    /// phase and the gear menu, which is the whole definition of "playing".
    /// </remarks>
    internal sealed class PortalRunner : MonoBehaviour
    {
        private static PortalRunner _instance;

        private float _deadline = -1f;
        private int _sceneHandle = -1;
        private CompletionFlow _flow;
        private GameScreens _screens;

        internal static PortalRunner Ensure()
        {
            if (_instance == null)
            {
                var host = new GameObject("[Portal]");
                DontDestroyOnLoad(host);
                _instance = host.AddComponent<PortalRunner>();
            }

            return _instance;
        }

        internal void StartTimeout(float seconds) => _deadline = Time.realtimeSinceStartup + seconds;

        private void Update()
        {
            if (_deadline >= 0f && Time.realtimeSinceStartup >= _deadline)
            {
                _deadline = -1f;
                Portal.TimedOut();
            }

            if (!Portal.IsReady)
            {
                return;
            }

            Portal.SetPlaying(PlayingNow());
        }

        private bool PlayingNow()
        {
            Scene scene = SceneManager.GetActiveScene();

            if (scene.handle != _sceneHandle || _flow == null)
            {
                _sceneHandle = scene.handle;
                _flow = FindFirstObjectByType<CompletionFlow>();
                _screens = FindFirstObjectByType<GameScreens>();
            }

            bool inTheClimb = _flow != null;
            CompletionPhase phase = inTheClimb ? _flow.Phase : CompletionPhase.Finished;
            bool menuOpen = _screens != null && _screens.MenuIsOpen;

            return GameplayRule.IsPlaying(inTheClimb, phase, menuOpen);
        }
    }
}
